export function linearRing(t,n,e,c){let l=0,r=t[e-c],g=t[e-c+1];for(;n<e;n+=c){const i=t[n],u=t[n+1];l+=g*i-r*u,r=i,g=u}return l/2}export function linearRings(t,n,e,c){let l=0;for(let r=0,g=e.length;r<g;++r){const i=e[r];l+=linearRing(t,n,i,c),n=i}return l}export function linearRingss(t,n,e,c){let l=0;for(let r=0,g=e.length;r<g;++r){const i=e[r];l+=linearRings(t,n,i,c),n=i[i.length-1]}return l}
